import * as React from "react"
import { motion, useMotionValue, useSpring } from "motion/react"
import { cn } from "@/lib/utils"
import {
  type MagneticButtonProps,
  MAGNETIC_DEFAULT_STRENGTH,
  MAGNETIC_DEFAULT_MAX_DISTANCE,
  MAGNETIC_SPRING_CONFIG,
} from "./magnetic-button-types"

function MagneticButton({
  children,
  strength = MAGNETIC_DEFAULT_STRENGTH,
  maxDistance = MAGNETIC_DEFAULT_MAX_DISTANCE,
  className,
  ...hostProps
}: MagneticButtonProps) {
  const x = useMotionValue(0)
  const y = useMotionValue(0)
  const springX = useSpring(x, MAGNETIC_SPRING_CONFIG)
  const springY = useSpring(y, MAGNETIC_SPRING_CONFIG)
  const [hasMoved, setHasMoved] = React.useState(false)

  const handleMouseMove = (e: React.MouseEvent<HTMLDivElement>) => {
    const rect = e.currentTarget.getBoundingClientRect()
    const cx = rect.left + rect.width / 2
    const cy = rect.top + rect.height / 2
    let dx = (e.clientX - cx) * strength
    let dy = (e.clientY - cy) * strength
    const distance = Math.hypot(dx, dy)
    if (distance > maxDistance) {
      const scale = maxDistance / distance
      dx *= scale
      dy *= scale
    }
    x.set(dx)
    y.set(dy)
    if (!hasMoved) setHasMoved(true)
  }

  const handleMouseLeave = () => {
    x.set(0)
    y.set(0)
    setHasMoved(false)
  }

  return (
    <div
      data-slot="magnetic-button"
      onMouseMove={handleMouseMove}
      onMouseLeave={handleMouseLeave}
      className={cn(
        "cursor-pointer rounded-lg border border-dashed transition-colors duration-150",
        "[--show-color:var(--color-blue-500)]",
        className,
      )}
      style={{
        borderColor: hasMoved ? "var(--show-color)" : "transparent",
        backgroundColor: hasMoved
          ? "color-mix(in srgb, var(--show-color) 20%, transparent)"
          : "transparent",
      }}
      {...hostProps}
    >
      <motion.div style={{ x: springX, y: springY }}>
        {children}
      </motion.div>
    </div>
  )
}

export { MagneticButton }

import type * as React from "react"

export type MagneticButtonProps = Omit<
  React.HTMLAttributes<HTMLDivElement>,
  "children" | "onMouseMove" | "onMouseLeave"
> & {
  /** Conteúdo do botão (será envolvido pelo motion.div magnético). */
  children: React.ReactNode
  /** Multiplicador de força do deslocamento (0..1). Padrão: 0.5 (mais sutil que o 0.8 do original). */
  strength?: number
  /** Distância máxima em px do cursor até o wrapper. Padrão: 100. */
  maxDistance?: number
}

export const MAGNETIC_DEFAULT_STRENGTH = 0.5
export const MAGNETIC_DEFAULT_MAX_DISTANCE = 100
export const MAGNETIC_SPRING_CONFIG = {
  stiffness: 150,
  damping: 25,
  mass: 0.1,
} as const
